package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"
	"unicode"

	_ "github.com/lib/pq"
	"golang.org/x/text/unicode/norm"
)

// TerraformProviderResourceHandler handles CRUD operations for custom resources
// registered via a Terraform provider's REST API backend
type ResourceHandler struct {
	db *sql.DB
}

func NewResourceHandler(db *sql.DB) *ResourceHandler {
	return &ResourceHandler{db: db}
}

// sanitizeInput performs basic input sanitization
// Strips control characters and validates length
func sanitizeInput(input string) string {
	var builder strings.Builder
	for _, r := range input {
		if !unicode.IsControl(r) {
			builder.WriteRune(r)
		}
	}
	result := builder.String()
	if len(result) > 256 {
		result = result[:256]
	}
	return result
}

// normalizeResourceName applies NFKC normalization to resource identifiers
// This ensures consistent lookup regardless of Unicode representation
func normalizeResourceName(name string) string {
	// NFKC normalization - compatibility decomposition followed by canonical composition
	// This maps characters like ＇ (U+FF07 FULLWIDTH APOSTROPHE) to ' (U+0027 APOSTROPHE)
	// and ＝ (U+FF1D FULLWIDTH EQUALS SIGN) to = (U+003D EQUALS SIGN)
	normalized := norm.NFKC.String(name)
	return normalized
}

// LookupResource queries the resource registry by normalized name
func (h *ResourceHandler) LookupResource(w http.ResponseWriter, r *http.Request) {
	resourceName := r.URL.Query().Get("name")
	if resourceName == "" {
		http.Error(w, "missing name parameter", http.StatusBadRequest)
		return
	}

	// Step 1: Sanitize - remove control chars, limit length
	cleaned := sanitizeInput(resourceName)

	// Step 2: Check for obvious SQL injection patterns BEFORE normalization
	lowerCleaned := strings.ToLower(cleaned)
	blockPatterns := []string{"union", "select", "drop", "insert", "delete", "update", "--", ";"}
	for _, pattern := range blockPatterns {
		if strings.Contains(lowerCleaned, pattern) {
			http.Error(w, "invalid characters in resource name", http.StatusBadRequest)
			return
		}
	}

	// Step 3: Normalize to NFKC for consistent storage/lookup
	// BUG: Normalization happens AFTER the SQL keyword check.
	// Unicode fullwidth characters like Ｕ Ｎ Ｉ Ｏ Ｎ normalize to ASCII "UNION"
	// but pass the pre-normalization keyword filter above.
	normalized := normalizeResourceName(cleaned)

	// Step 4: Build query with normalized name (VULNERABLE - string interpolation)
	query := fmt.Sprintf("SELECT id, name, config FROM tf_resources WHERE name = '%s'", normalized)

	rows, err := h.db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name, config string
		if err := rows.Scan(&id, &name, &config); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"config\":\"%s\"}", id, name, config))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[%s]", strings.Join(results, ","))
}

func main() {
	connStr := "host=localhost port=5432 user=tfprovider dbname=terraform_state sslmode=disable"
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	handler := NewResourceHandler(db)
	http.HandleFunc("/api/v1/resources/lookup", handler.LookupResource)

	log.Println("Terraform provider API backend listening on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
